#include <bits/stdc++.h>
using namespace std;

const int INF = 1000000000;

struct Edge {
    int to, capacity, cost, flow;
    size_t rev;
};

void addLink(vector<vector<Edge>>& graph, int from, int to, int cap, int cst) {
    Edge e1 = {to, cap, cst, 0, graph[to].size()};
    Edge e2 = {from, 0, -cst, 0, graph[from].size()};
    graph[from].push_back(e1);
    graph[to].push_back(e2);
}

int main() {
    int N, m, k, c, d;
    scanf("%d %d %d %d %d", &N, &m, &k, &c, &d);
    int total_nodes = N * 101 + 2;
    vector<vector<Edge>> g(total_nodes);
    for (int i = 0; i < k; i++) {
        int x;
        scanf("%d", &x);
        x--;
        addLink(g, total_nodes - 2, x * 101, 1, 0);
    }
    for (int i = 0; i < 101; i++) {
        addLink(g, i, total_nodes - 1, INF, i * c);
    }
    for (int i = 1; i < N; i++) {
        for (int j = 0; j + 1 < 101; j++) {
            addLink(g, i * 101 + j, i * 101 + j + 1, INF, 0);
        }
    }
    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        u--; v--;
        for (int j = 0; j + 1 < 101; j++) {
            for (int K = 1; K <= k; K++) {
                int cost_diff = d * K * K - d * (K - 1) * (K - 1);
                addLink(g, u * 101 + j, v * 101 + j + 1, 1, cost_diff);
                addLink(g, v * 101 + j, u * 101 + j + 1, 1, cost_diff);
            }
        }
    }
    int s = total_nodes - 2;
    int t = total_nodes - 1;
    int total_flow = 0, total_cost = 0;
    while (total_flow < k) {
        vector<int> dist(total_nodes, INF);
        vector<int> parent(total_nodes, -1);
        vector<size_t> parent_edge(total_nodes);
        queue<int> q;
        dist[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (size_t i=0; i<g[v].size(); ++i) {
                Edge &e = g[v][i];
                if (e.flow < e.capacity && dist[v] + e.cost < dist[e.to]) {
                    dist[e.to] = dist[v] + e.cost;
                    parent[e.to] = v;
                    parent_edge[e.to] = i;
                    q.push(e.to);
                }
            }
        }
        if (dist[t] == INF) break;
        int add_flow = k - total_flow;
        for (int v = t; v != s; v = parent[v]) {
            int pv = parent[v];
            size_t ei = parent_edge[v];
            add_flow = min(add_flow, g[pv][ei].capacity - g[pv][ei].flow);
        }
        for (int v = t; v != s; v = parent[v]) {
            int pv = parent[v];
            size_t ei = parent_edge[v];
            g[pv][ei].flow += add_flow;
            g[v][g[pv][ei].rev].flow -= add_flow;
            total_cost += g[pv][ei].cost * add_flow;
        }
        total_flow += add_flow;
    }
    printf("%d\n", total_cost);
}
